<script setup lang="ts">
definePageMeta({layout:'admin'})
const {api,message,session}=useCmsAdmin(),editing=ref<any>(null),error=ref(''),busy=ref(false)
const {data:users,refresh,error:loadError}=await useAsyncData<any[]>('cms-users',()=>api('users'))
function create(){editing.value={email:'',name:'',role:'editor',disabled:false,password:''};error.value=''}
async function save(){busy.value=true;error.value='';try{await api('users'+(editing.value.id?'/'+editing.value.id:''),{method:'POST',body:editing.value});if(editing.value.id===session.value.id){await navigateTo('/admin/login');return}editing.value=null;await refresh()}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><div class="cms-page"><p v-if="loadError" class="cms-error" role="alert">{{ useCmsAdmin().message(loadError) }}</p><div class="cms-heading"><h1>帳號管理</h1><button class="cms-button cms-button-gold" @click="create">新增帳號</button></div><div class="cms-panel"><button v-for="u in users" :key="u.id" class="cms-resource-row" @click="editing={...u,password:''};error='' "><strong>{{ u.name }}</strong><span>{{ u.email }} · {{ u.role==='admin'?'管理員':'編輯者' }} · {{ u.disabled?'已停用':'啟用中' }}</span></button></div><AdminDialog :open="!!editing" title="帳號設定" @close="editing=null"><form v-if="editing" class="cms-form" @submit.prevent="save"><label>姓名<input v-model="editing.name" required /></label><label>Email<input v-model="editing.email" type="email" required /></label><label>角色<select v-model="editing.role"><option value="editor">編輯者</option><option value="admin">管理員</option></select></label><label>臨時密碼<input v-model="editing.password" type="password" autocomplete="new-password" minlength="12" :required="!editing.id" placeholder="至少 12 字；不重設時留空" /></label><label><input v-model="editing.disabled" type="checkbox" />停用帳號</label><p v-if="error" class="cms-error" role="alert">{{ error }}</p><button class="cms-button cms-button-gold" :disabled="busy">儲存帳號</button></form></AdminDialog></div></template>
